# Routing workflow: a cheap model classifies, then a fixed branch runs.
# call_model(model, prompt) stands for any provider's API call.
def handle_ticket(text, call_model):
    label = call_model("small-fast-model",
        f"Label as refund, technical or other. Reply with the label only.\n\n{text}").strip()

    if label == "refund":
        return call_model("small-fast-model", f"Draft a refund reply using our policy:\n{text}")
    if label == "technical":
        return call_model("large-reasoning-model", f"Diagnose and draft a fix:\n{text}")
    return "Forward to a human"     # unknown cases go to staff

# Usage with a fake model for testing:
fake = lambda model, prompt: "refund" if prompt.startswith("Label") else f"[{model}] reply"
print(handle_ticket("I was charged twice", fake))   # [small-fast-model] reply
